<label>Midline y =: <output id="midlineSliderVal">1</output><input id="midlineSliderInput" type="range" min="-1" max="3" step="0.5" value="1" oninput="update_midlineSlider(+this.value)"></label>
<label>Period: <output id="periodSliderVal">π</output><input id="periodSliderInput" type="range" min="1.57" max="6.28" step="0.785" value="3.14" oninput="update_periodSlider(+this.value)"></label>
