// @FIGURE_CODE_BEGIN
var state = { A: 3, K: 1, T: Math.PI };
var hitRegions = [];

/* ── formatting helpers ─────────────────────────────────────────────── */
function fmt(v) { return String(Math.round(v * 100) / 100); }
function gcd(a, b) { return b ? gcd(b, a % b) : a; }
function formatPeriod(p) {
  var k = Math.round(p / (Math.PI / 4));
  if (Math.abs(p - k * Math.PI / 4) < 0.02) {
    var map = { 1: 'π/4', 2: 'π/2', 3: '3π/4', 4: 'π', 5: '5π/4', 6: '3π/2', 7: '7π/4', 8: '2π' };
    if (map[k]) return map[k];
  }
  return fmt(p);
}
function bCoeff() {
  var k = Math.round(state.T / (Math.PI / 4));
  if (Math.abs(state.T - k * Math.PI / 4) < 0.02 && k > 0) {
    var g = gcd(8, k), num = 8 / g, den = k / g;
    if (den === 1) return num === 1 ? '' : String(num);
    return '(' + num + '/' + den + ')';
  }
  return fmt(2 * Math.PI / state.T);
}
function equationStr() {
  return 'y = ' + fmt(state.K) + ' + ' + fmt(state.A) + '·sin(' + bCoeff() + 'x)';
}

/* ── chart setup ────────────────────────────────────────────────────── */
var container = document.getElementById('container');
var canvas = document.createElement('canvas');
canvas.style.cssText = 'width:100%;height:100%;display:block';
container.appendChild(canvas);

function curveData() {
  var pts = [], N = 260, xmax = state.T * 1.25;
  for (var i = 0; i <= N; i++) {
    var x = xmax * i / N;
    pts.push({ x: x, y: state.K + state.A * Math.sin(2 * Math.PI * x / state.T) });
  }
  return pts;
}

function drawAnnotations(chart) {
  var ctx = chart.ctx, area = chart.chartArea, xs = chart.scales.x, ys = chart.scales.y;
  function X(v) { return xs.getPixelForValue(v); }
  function Y(v) { return ys.getPixelForValue(v); }
  var s = Math.max(0.6, Math.min(area.width, area.height) / 360);
  var fs = Math.max(9, Math.round(12 * s));
  var ah = 7 * s, lw = Math.max(1, 1.5 * s);
  hitRegions.length = 0;
  ctx.save();

  function head(fx, fy, tx, ty, color) {
    var a = Math.atan2(ty - fy, tx - fx);
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(tx, ty);
    ctx.lineTo(tx - ah * Math.cos(a - 0.42), ty - ah * Math.sin(a - 0.42));
    ctx.lineTo(tx - ah * Math.cos(a + 0.42), ty - ah * Math.sin(a + 0.42));
    ctx.closePath(); ctx.fill();
  }
  function arrow(x0, y0, x1, y1, color, w, both) {
    ctx.strokeStyle = color; ctx.lineWidth = w; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
    head(x0, y0, x1, y1, color);
    if (both) head(x1, y1, x0, y0, color);
  }
  function txt(str, x, y, color, align, baseline, font) {
    ctx.font = font || (fs + 'px sans-serif');
    ctx.textAlign = align || 'left'; ctx.textBaseline = baseline || 'middle';
    ctx.lineWidth = 3; ctx.strokeStyle = 'rgba(255,255,255,0.9)'; ctx.lineJoin = 'round';
    ctx.strokeText(str, x, y);
    ctx.fillStyle = color; ctx.fillText(str, x, y);
    return ctx.measureText(str).width;
  }

  /* axes with arrowheads */
  var xAxisY = Math.min(Y(0), area.bottom - 2);
  var yAxisX = Math.max(X(0), area.left + 2);
  arrow(area.left, xAxisY, area.right + ah + 4, xAxisY, '#000', lw);
  arrow(yAxisX, area.bottom, yAxisX, area.top - ah - 4, '#000', lw);
  txt('x', area.right + ah + 8, xAxisY + 1, '#000', 'left', 'middle', 'italic bold ' + fs + 'px sans-serif');
  txt('y', yAxisX - 6, area.top - ah - 6, '#000', 'right', 'middle', 'italic bold ' + fs + 'px sans-serif');

  /* y tick marks + integer labels */
  ctx.strokeStyle = '#000'; ctx.lineWidth = lw;
  for (var v = Math.ceil(ys.min); v <= Math.floor(ys.max); v++) {
    var ty = Y(v);
    ctx.beginPath(); ctx.moveTo(yAxisX - 3.5 * s, ty); ctx.lineTo(yAxisX + 3.5 * s, ty); ctx.stroke();
    if (v === 0) txt('0', yAxisX - 6 * s, xAxisY + 3 + fs * 0.5, '#000', 'right', 'middle', (fs - 1) + 'px sans-serif');
    else txt(String(v), yAxisX - 6 * s, ty, '#000', 'right', 'middle', (fs - 1) + 'px sans-serif');
  }
  /* x ticks at half and full period */
  var xt = [state.T / 2, state.T];
  for (var i = 0; i < 2; i++) {
    var tx2 = X(xt[i]);
    ctx.beginPath(); ctx.moveTo(tx2, xAxisY - 3.5 * s); ctx.lineTo(tx2, xAxisY + 3.5 * s); ctx.stroke();
    txt(formatPeriod(xt[i]), tx2, xAxisY + 5 + fs * 0.55, '#000', 'center', 'middle', (fs - 1) + 'px sans-serif');
  }

  /* midline: orange horizontal arrow */
  var my = Y(state.K), mEnd = X(state.T * 1.06);
  arrow(yAxisX, my, mEnd, my, '#e07b1f', Math.max(1.2, 1.7 * s));
  var mLab = 'Midline: y = ' + fmt(state.K);
  var mw = txt(mLab, mEnd + ah + 6, my, '#e07b1f', 'left', 'middle', 'bold ' + fs + 'px sans-serif');
  var mMeta = { tip: mLab + ' — the vertical center of the wave', title: 'Midline',
    body: 'The midline y = ' + fmt(state.K) + ' is the horizontal line the wave oscillates around. Moving it shifts the whole curve up or down without changing its height or width.' };
  hitRegions.push({ x0: yAxisX, y0: my, x1: mEnd, y1: my, tip: mMeta.tip, title: mMeta.title, body: mMeta.body });
  hitRegions.push({ x0: mEnd + ah + 6, y0: my - 7, x1: mEnd + ah + 6 + mw, y1: my + 7, tip: mMeta.tip, title: mMeta.title, body: mMeta.body });

  /* amplitude: teal vertical arrow midline → peak, with leader to label */
  var ax = X(state.T / 4), top = Y(state.K + state.A);
  arrow(ax, my, ax, top, '#128a8a', Math.max(1.2, 1.7 * s));
  var aLab = 'Amplitude: |A| = ' + fmt(state.A);
  var alx = X(state.T * 0.52), aly = Math.max(area.top + fs * 0.7, top - 16 * s);
  var aw = txt(aLab, alx, aly, '#128a8a', 'left', 'middle', 'bold ' + fs + 'px sans-serif');
  ctx.strokeStyle = '#128a8a'; ctx.lineWidth = Math.max(0.8, s);
  ctx.beginPath(); ctx.moveTo(alx - 4, aly + fs * 0.35); ctx.lineTo(ax + 3, top + (my - top) * 0.35); ctx.stroke();
  var aMeta = { tip: aLab + ' — distance from midline to peak', title: 'Amplitude',
    body: 'The amplitude |A| = ' + fmt(state.A) + ' is the distance from the midline to a peak (or trough). Stretching it changes only the wave\'s height — the midline and period stay fixed.' };
  hitRegions.push({ x0: ax, y0: my, x1: ax, y1: top, tip: aMeta.tip, title: aMeta.title, body: aMeta.body });
  hitRegions.push({ x0: alx, y0: aly - 7, x1: alx + aw, y1: aly + 7, tip: aMeta.tip, title: aMeta.title, body: aMeta.body });

  /* period: red double-headed arrow below the plot */
  var py2 = Y(state.K - state.A - 0.9);
  arrow(X(0), py2, X(state.T), py2, '#c0392b', Math.max(1.2, 1.7 * s), true);
  var pLab = 'Period = ' + formatPeriod(state.T);
  var pw = txt(pLab, X(state.T) + ah + 6, py2, '#c0392b', 'left', 'middle', 'bold ' + fs + 'px sans-serif');
  var pMeta = { tip: pLab + ' — length of one full cycle', title: 'Period',
    body: 'The period T = ' + formatPeriod(state.T) + ' is the horizontal length of one complete cycle. Changing it squeezes or stretches the wave sideways while the midline and amplitude are untouched.' };
  hitRegions.push({ x0: X(0), y0: py2, x1: X(state.T), y1: py2, tip: pMeta.tip, title: pMeta.title, body: pMeta.body });
  hitRegions.push({ x0: X(state.T) + ah + 6, y0: py2 - 7, x1: X(state.T) + ah + 6 + pw, y1: py2 + 7, tip: pMeta.tip, title: pMeta.title, body: pMeta.body });

  ctx.restore();
}

var chart = new Chart(canvas.getContext('2d'), {
  type: 'line',
  data: { datasets: [{ data: curveData(), borderColor: '#1a4f9c', borderWidth: 2.5, pointRadius: 0, tension: 0 }] },
  options: {
    responsive: true, maintainAspectRatio: false, animation: false, events: [],
    layout: { padding: { right: 112, top: 34, left: 22, bottom: 46 } },
    scales: {
      x: { type: 'linear', min: 0, max: state.T * 1.25, display: false },
      y: { min: state.K - state.A - 1.6, max: state.K + state.A + 1.6, display: false }
    },
    plugins: { legend: { display: false }, tooltip: { enabled: false } }
  },
  plugins: [{ id: 'annotations', afterDraw: drawAnnotations }]
});
window.__markRendered();

/* ── hover / click ──────────────────────────────────────────────────── */
function distSeg(px, py, r) {
  var dx = r.x1 - r.x0, dy = r.y1 - r.y0, L2 = dx * dx + dy * dy;
  var t = L2 ? ((px - r.x0) * dx + (py - r.y0) * dy) / L2 : 0;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(px - (r.x0 + t * dx), py - (r.y0 + t * dy));
}
function hitTest(mx, my) {
  var best = null, bestD = 14;
  for (var i = 0; i < hitRegions.length; i++) {
    var d = distSeg(mx, my, hitRegions[i]);
    if (d < bestD) { bestD = d; best = hitRegions[i]; }
  }
  var xv = chart.scales.x.getValueForPixel(mx);
  if (xv != null && xv >= 0 && xv <= state.T * 1.25) {
    var yv = state.K + state.A * Math.sin(2 * Math.PI * xv / state.T);
    var dc = Math.abs(my - chart.scales.y.getPixelForValue(yv));
    if (dc < bestD) {
      best = { tip: equationStr(), title: 'The sinusoid',
        body: 'Every point on this curve satisfies ' + equationStr() + '. The three sliders set the midline, amplitude and period independently — together those three numbers determine this exact curve.' };
    }
  }
  return best;
}
canvas.addEventListener('mousemove', function (e) {
  var rect = canvas.getBoundingClientRect();
  var hit = hitTest(e.clientX - rect.left, e.clientY - rect.top);
  if (hit) { showTooltip(hit.tip, e); canvas.style.cursor = 'pointer'; }
  else { hideTooltip(); canvas.style.cursor = 'default'; }
});
canvas.addEventListener('mouseout', function () { hideTooltip(); });
canvas.addEventListener('click', function (e) {
  var rect = canvas.getBoundingClientRect();
  var hit = hitTest(e.clientX - rect.left, e.clientY - rect.top);
  if (hit) showPopup(hit.title, hit.body);
});

/* ── controls ───────────────────────────────────────────────────────── */
function refresh() {
